// ============================================================================
//
//	AB·CLOUD · MERIDIAN OBSERVATORY UNIFIED STANDALONE  —  GO PORT (unified)
//
// ============================================================================
//
//	ЕДИНЫЙ АВТОНОМНЫЙ ФАЙЛ (unified single-file standalone).
//
//	ЧТО ЭТО ТАКОЕ
//	-------------
//	Полностью автономный однофайловый порт вычислительного ядра сюиты
//	meridian-spectral-observatory (эталон: ab_cloud_full.jl +
//	hp_audit_standalone.jl + AB_Cloud_Monumental_v6_3.jl), объединяющий
//	в одном файле:
//
//	  • ядро ABCloud — 199 якорных проверок против golden-эталона Julia,
//	    бит-в-бит паритет с непромодифицированным ядром ports/go/main.go;
//	  • AURORA-консоль в стиле HP·MERIDIAN (❖/◆-орнаменты, брайль-лестница
//	    ⣀⣄⣤⣦⣶⣷⣿, truecolor-градиент cyan→violet→gold, блок-баннер ██╗);
//	  • полный набор отчётов: REPORT.txt, final_report.md и самодостаточный
//	    AURORA-HTML с анимированным verdict-кольцом (conic-gradient);
//	  • 600-dpi PNG-графики (3600×2250, 2× supersample) с числовыми
//	    аннотациями — собственный PNG-энкодер (stored-deflate btype 00,
//	    ручные CRC32/adler32), без внешних зависимостей.
//
//	ЗАПУСК
//	------
//	  go run abcloud_unified.go                 # интерактивное меню
//	  go run abcloud_unified.go menu            # то же, явно
//	  go run abcloud_unified.go selftest        # 199/199 якорей
//	  go run abcloud_unified.go report          # отчёт-пакет (txt+md+html)
//	  go run abcloud_unified.go plots           # 600-dpi PNG-батарея
//	  go run abcloud_unified.go help            # все команды
//
//	Данные (50 000 нулей дзета и golden-эталон) ВСТРОЕНЫ в файл
//	(zlib+base64): сетевой доступ и внешние файлы не нужны. Флаги
//	--data/--golden по-прежнему принимают реальные пути с диска.
//
//	Верификация: selftest 199/199 — bit-exact против Julia-эталона
//	(gen_golden.jl, julia 1.10.9, n_zeros = 50000,
//	gamma1 = 14.134725142, gammaN = 40433.687385462).
//
//	Сборка:  go build -o abcloud abcloud_unified.go   (только stdlib, go >= 1.22)
//
// ============================================================================
//
// abcloud — Go port of the meridian-spectral-observatory suite.
//
// Bit-faithful kernel port of ab_cloud_full.jl / hp_audit_standalone.jl /
// AB_Cloud_Monumental_v6_3.jl (computational core), mirroring abcloud_port.cpp
// and the Rust port. No external dependencies — standard library only.
//
// Eigenvalues: cyclic Jacobi for complex Hermitian matrices (no LAPACK;
// agrees with LAPACK to ~1e-12 — inside the golden tolerances).
// Disorder note: W>0 residual eps uses the portable classic MT19937 (Julia
// uses dSFMT — documented divergence; all golden anchors are W=0).
// ============================================================================
package main

import (
	"bufio"
	"bytes"
	"compress/zlib"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"math"
	"math/cmplx"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"time"
)

