const abBrand = "AB·CLOUD · MERIDIAN OBSERVATORY UNIFIED STANDALONE"
const abVersion = "1.0.0-unified-go"

var auroraMode = "none"

// auroraProbe — truecolor → none, honoring NO_COLOR / FORCE_COLOR / TTY.
// isatty via syscall fallback: os.Stdout.Stat() mode & os.ModeCharDevice.
func auroraProbe() string {
	if os.Getenv("NO_COLOR") != "" {
		auroraMode = "none"
	} else if os.Getenv("FORCE_COLOR") != "" {
		auroraMode = "truecolor"
	} else if stdoutIsTTY() && os.Getenv("TERM") != "dumb" {
		auroraMode = "truecolor"
	} else {
		auroraMode = "none"
	}
	return auroraMode
}

func stdoutIsTTY() bool {
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return fi.Mode()&os.ModeCharDevice != 0
}

// cR — dynamic reset; mode is probed at runtime, not init time.
func cR() string {
	if auroraMode != "none" {
		return "\x1b[0m"
	}
	return ""
}

func cRGB(r, g, b int) string {
	if auroraMode != "truecolor" {
		return ""
	}
	clamp := func(v int) int {
		if v < 0 {
			return 0
		}
		if v > 255 {
			return 255
		}
		return v
	}
	return fmt.Sprintf("\x1b[38;2;%d;%d;%dm", clamp(r), clamp(g), clamp(b))
}

// c — AURORA palette keys: fg dim ok warn bad gold vio cyan mint sky rose.
func c(txt, key string) string {
	if auroraMode == "none" {
		return txt
	}
	pal := map[string][3]int{
		"fg":   {214, 226, 235},
		"dim":  {108, 124, 138},
		"ok":   {126, 231, 135},
		"warn": {255, 199, 95},
		"bad":  {255, 107, 107},
		"gold": {255, 215, 95},
		"vio":  {167, 130, 255},
		"cyan": {97, 218, 251},
		"mint": {125, 255, 212},
		"sky":  {143, 216, 255},
		"rose": {255, 143, 196},
	}
	rgb, has := pal[key]
	if !has {
		rgb = pal["fg"]
	}
	return cRGB(rgb[0], rgb[1], rgb[2]) + txt + cR()
}

// gradRGB — cyan (97,218,251) → violet (167,130,255) → gold (255,215,95).
func gradRGB(t float64) (int, int, int) {
	stops := []struct {
		t float64
		c [3]int
	}{{0.0, [3]int{97, 218, 251}}, {0.5, [3]int{167, 130, 255}}, {1.0, [3]int{255, 215, 95}}}
	if t < 0 {
		t = 0
	}
	if t > 1 {
		t = 1
	}
	for i := 0; i+1 < len(stops); i++ {
		if t <= stops[i+1].t {
			k := (t - stops[i].t) / (stops[i+1].t - stops[i].t)
			r := float64(stops[i].c[0]) + k*float64(stops[i+1].c[0]-stops[i].c[0])
			g := float64(stops[i].c[1]) + k*float64(stops[i+1].c[1]-stops[i].c[1])
			b := float64(stops[i].c[2]) + k*float64(stops[i+1].c[2]-stops[i].c[2])
			return int(r), int(g), int(b)
		}
	}
	return stops[len(stops)-1].c[0], stops[len(stops)-1].c[1], stops[len(stops)-1].c[2]
}

// gradPaint — paint a plain row through the AURORA gradient column by column.
func gradPaint(txt string) string {
	if auroraMode == "none" {
		return txt
	}
	n := 0
	for range txt {
		n++
	}
	if n == 0 {
		return txt
	}
	var out strings.Builder
	i := 0
	for _, ch := range txt {
		if ch == ' ' {
			out.WriteRune(ch)
		} else {
			t := 0.5
			if n > 1 {
				t = (float64(i) + 0.5) / float64(n)
			}
			r, g, b := gradRGB(t)
			out.WriteString(cRGB(r, g, b))
			out.WriteRune(ch)
		}
		i++
	}
	out.WriteString(cR())
	return out.String()
}

