func bigtext(word string) []string {
	rows := []string{"", "", "", "", "", ""}
	for _, ch := range word {
		gl, has := bigfont[ch]
		if !has {
			continue
		}
		for i := 0; i < 6; i++ {
			rows[i] += gl[i] + " "
		}
	}
	return rows
}

func badge(txt, key string) string {
	return c("⟦ ", "dim") + c(txt, key) + c(" ⟧", "dim")
}

func rule() string { return ruleW(78, "vio") }

func ruleW(width int, key string) string {
	if width < 7 {
		width = 7
	}
	return c(strings.Repeat("─", 3)+" ❖ "+strings.Repeat("─", width-7), key)
}

func kv(k, v string) string {
	pad := strings.Repeat(".", maxInt(2, 30-len([]rune(k))))
	return c("  "+k+" ", "fg") + c(pad, "dim") + " " + c(v, "gold")
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

// brailleBar — braille ladder ⣀⣄⣤⣦⣶⣷⣿ over a slate ⣀ track, gradient-filled.
func brailleBar(p float64, width int) string {
	lad := []rune("⣀⣄⣤⣦⣶⣷⣿")
	if p < 0 {
		p = 0
	}
	if p > 1 {
		p = 1
	}
	full := int(p * float64(width))
	frac := p*float64(width) - float64(full)
	var cells strings.Builder
	for i := 0; i < width; i++ {
		switch {
		case i < full:
			k := float64(i+1) / float64(width)
			col := ""
			if auroraMode != "none" {
				r, g, b := gradRGB(k)
				col = cRGB(r, g, b)
			}
			cells.WriteString(col + "⣿" + cR())
		case i == full && frac > 0.02:
			idx := int(frac * 7)
			if idx > 6 {
				idx = 6
			}
			cells.WriteString(c(string(lad[idx]), "dim"))
		default:
			cells.WriteString(c("⣀", "dim"))
		}
	}
	return cells.String() + c(fmt.Sprintf(" %5.1f%%", p*100), "dim")
}

// selftestProgress — the hook the kernel calls once per golden section.
var selftestProgress func(done, total int)

// installSelftestBar — live braille-ladder bar on stderr during the loop.
func installSelftestBar() {
	selftestProgress = func(done, total int) {
		if auroraMode == "none" {
			return
		}
		p := float64(done) / float64(maxInt(total, 1))
		fmt.Fprintf(os.Stderr, "\r  %s\x1b[0K", brailleBar(p, 28))
		if done >= total {
			fmt.Fprint(os.Stderr, "\n")
		}
	}
}

func auroraSilenceBar() { selftestProgress = nil }

// banner — block-letter wordmark, gradient-shaded, with the identity frame.
func banner() {
	fmt.Println()
	for _, row := range bigtext("AB·CLOUD") {
		fmt.Println("  " + gradPaint(row))
	}
	fmt.Println("  " + c(strings.Repeat("═", 66), "dim"))
	fmt.Println("  " + gradPaint("◆ MERIDIAN OBSERVATORY · UNIFIED STANDALONE ◆"))
	fmt.Println("  " + c("brand: "+abBrand, "dim"))
	fmt.Println("  " + rule())
}

func sectionHead(title string) {
	fmt.Println()
	fmt.Println("  " + c("❖ "+title, "vio"))
	fmt.Println("  " + c(strings.Repeat("─", 74), "dim"))
}

