// DOCTOR — environment probe.
// ══════════════════════════════════════════════════════════════════════════════

func doctor() bool {
	fmt.Println()
	fmt.Println("  " + c("◆ DOCTOR — environment probe", "vio"))
	fmt.Println("  " + rule())
	zc, gsec, errc := embeddedHealth()
	rows := [][2]string{
		{"go", runtime.Version()},
		{"os/arch", runtime.GOOS + "/" + runtime.GOARCH},
		{"brand", abBrand},
		{"color mode", auroraMode},
		{"term", orDash(os.Getenv("TERM"))},
		{"embedded blobs", fmt.Sprintf("zeros50k (%d B zb64), golden (%d B zb64)",
			len(embZeros50kB64), len(embGoldenB64))},
		{"zeros50k", fmt.Sprintf("%d values", zc)},
		{"golden", fmt.Sprintf("%d sections", gsec)},
	}
	ok := errc == nil && zc == 50000 && gsec == 37
	if errc != nil {
		rows = append(rows, [2]string{"payload", "ERROR: " + errc.Error()})
	}
	for _, r := range rows {
		fmt.Println(kv(fmt.Sprintf("%-14s", r[0]), r[1]))
	}
	verdict := badge("UNHEALTHY", "bad")
	if ok {
		verdict = badge("SANE", "ok")
	}
	fmt.Println("  verdict: " + verdict)
	return ok
}

func orDash(s string) string {
	if s == "" {
		return "?"
	}
	return s
}

// ══════════════════════════════════════════════════════════════════════════════
// INTERACTIVE MENU — the AURORA loop.
// ══════════════════════════════════════════════════════════════════════════════

const abMenu = "\n" +
	"  ◆ MAIN MENU — AB·CLOUD MERIDIAN UNIFIED STANDALONE\n" +
	"  ──────────────────────────────────────────────────────────────\n" +
	"   1) golden selftest        (199 anchors, bit-exact parity)\n" +
	"   2) zeros battery          (spacings / KS / CvM / AD)\n" +
	"   3) bN ladder sweep\n" +
	"   4) full report package    (txt + md + html)\n" +
	"   5) doctor                 (environment probe)\n" +
	"   0) banner                 (wordmark + identity)\n" +
	"   q) quit\n"

func menuLoop() {
	banner()
	sc := bufio.NewScanner(os.Stdin)
	for {
		fmt.Print(abMenu)
		fmt.Print("  select ❖ ")
		if !sc.Scan() {
			fmt.Println()
			fmt.Println("  " + c("◆ until the next meridian — goodbye", "vio"))
			return
		}
		ch := strings.ToLower(strings.TrimSpace(sc.Text()))
		switch ch {
		case "1":
			selftestRun(false)
		case "2":
			zerosRun()
		case "3":
			sweepRun(true)
		case "4":
			reportRun()
		case "5":
			doctor()
		case "0":
			banner()
		case "q", "quit", "exit":
			fmt.Println("  " + c("◆ until the next meridian — goodbye", "vio"))
			return
		default:
			fmt.Println("  " + c("unknown choice: "+ch, "warn"))
		}
	}
}

// ═══ PNG PLOT ENGINE (600 dpi) ═══

// ══════════════════════════════════════════════════════════════════════════════
// AURORA PLOTS — dependency-free 600-dpi PNG engine.
// Stored-deflate PNG writer (hand-rolled CRC32 table + adler32, btype 00),
// stroke-font renderer, ss=2 supersampled canvas box-downsampled to the
// 3600×2250 output. Charts carry numeric annotations (en).
// ══════════════════════════════════════════════════════════════════════════════

var abCrcTab [256]uint32

func abCrc32(data []byte) uint32 {
	if abCrcTab[1] == 0 {
		for n := 0; n < 256; n++ {
			c := uint32(n)
			for k := 0; k < 8; k++ {
				if c&1 != 0 {
					c = (c >> 1) ^ 0xEDB88320
				} else {
					c >>= 1
				}
			}
			abCrcTab[n] = c
		}
	}
	c := uint32(0xFFFFFFFF)
	for _, b := range data {
		c = abCrcTab[(c^uint32(b))&0xFF] ^ (c >> 8)
	}
	return c ^ 0xFFFFFFFF
}

func abAdler32(data []byte) uint32 {
	const mod = 65521
	a, b := uint32(1), uint32(0)
	for _, by := range data {
		a = (a + uint32(by)) % mod
		b = (b + a) % mod
	}
	return b<<16 | a
}

func abPngChunk(tag string, payload []byte) []byte {
	out := make([]byte, 0, len(payload)+12)
	var lenBe [4]byte
	n := uint32(len(payload))
	lenBe[0], lenBe[1], lenBe[2], lenBe[3] = byte(n>>24), byte(n>>16), byte(n>>8), byte(n)
	out = append(out, lenBe[:]...)
	out = append(out, tag...)
	out = append(out, payload...)
	crc := abCrc32(append([]byte(tag), payload...))
	out = append(out, byte(crc>>24), byte(crc>>16), byte(crc>>8), byte(crc))
	return out
}

// abPngEncode — 8-bit RGBA PNG, IDAT = zlib stream of stored deflate blocks
// (btype 00): 0x78 0x01, [hdr len nlen data]*, adler32. Hand-rolled.
func abPngEncode(rgba []byte, w, h int) []byte {
	raw := make([]byte, 0, h*(1+w*4))
	stride := w * 4
	for y := 0; y < h; y++ {
		raw = append(raw, 0) // filter: none
		raw = append(raw, rgba[y*stride:(y+1)*stride]...)
	}
	var z bytes.Buffer
	z.WriteByte(0x78)
	z.WriteByte(0x01)
	i, n := 0, len(raw)
	for {
		end := i + 65535
		if end > n {
			end = n
		}
		blk := raw[i:end]
		last := end >= n
		hdr := byte(0)
		if last {
			hdr = 1 // BFINAL=1, BTYPE=00 (stored)
		}
		z.WriteByte(hdr)
		l := len(blk)
		z.WriteByte(byte(l & 0xFF))
		z.WriteByte(byte(l >> 8))
		nl := l ^ 0xFFFF
		z.WriteByte(byte(nl & 0xFF))
		z.WriteByte(byte(nl >> 8))
		z.Write(blk)
		i = end
		if last {
			break
		}
	}
	ad := abAdler32(raw)
	z.Write([]byte{byte(ad >> 24), byte(ad >> 16), byte(ad >> 8), byte(ad)})
	var ihdr []byte
	ihdr = append(ihdr, byte(w>>24), byte(w>>16), byte(w>>8), byte(w))
	ihdr = append(ihdr, byte(h>>24), byte(h>>16), byte(h>>8), byte(h))
	ihdr = append(ihdr, 8, 6, 0, 0, 0) // 8-bit RGBA
	var out bytes.Buffer
	out.Write([]byte{0x89, 'P', 'N', 'G', '\r', '\n', 0x1A, '\n'})
	out.Write(abPngChunk("IHDR", ihdr))
	out.Write(abPngChunk("IDAT", z.Bytes()))
	out.Write(abPngChunk("IEND", nil))
	return out.Bytes()
}

// ── canvas (ss=2 supersample, logical 3600×2250) ─────────────────────────────

type abRGBA struct{ R, G, B, A uint8 }

var (
	colCy  = abRGBA{97, 218, 251, 255}
	colVi  = abRGBA{167, 130, 255, 255}
	colGo  = abRGBA{255, 215, 95, 255}
	colMn  = abRGBA{125, 255, 212, 255}
	colRs  = abRGBA{255, 143, 196, 255}
	colSl  = abRGBA{108, 124, 138, 255}
	colFg  = abRGBA{214, 226, 235, 255}
	plotSS = 2
	plotW  = 3600
	plotH  = 2250
)

func gradCol(t float64, a uint8) abRGBA {
	r, g, b := gradRGB(t)
	return abRGBA{uint8(r), uint8(g), uint8(b), a}
}

type abPt struct{ X, Y float64 }

type abCanvas struct {
	LW, LH int    // logical size
	buf    []byte // supersampled RGBA
}

func newCanvas(lw, lh int) *abCanvas {
	cv := &abCanvas{LW: lw, LH: lh, buf: make([]byte, lw*plotSS*lh*plotSS*4)}
	bg := [4]byte{12, 16, 28, 255}
	for i := 0; i < len(cv.buf); i += 4 {
		cv.buf[i], cv.buf[i+1], cv.buf[i+2], cv.buf[i+3] = bg[0], bg[1], bg[2], bg[3]
	}
	return cv
}

func (cv *abCanvas) fillRect(x, y, w, h float64, col abRGBA) {
	x0 := int(math.Floor(x * float64(plotSS)))
	y0 := int(math.Floor(y * float64(plotSS)))
	x1 := int(math.Ceil((x + w) * float64(plotSS)))
	y1 := int(math.Ceil((y + h) * float64(plotSS)))
	W := cv.LW * plotSS
	H := cv.LH * plotSS
	if x0 < 0 {
		x0 = 0
	}
	if y0 < 0 {
		y0 = 0
	}
	if x1 > W {
		x1 = W
	}
	if y1 > H {
		y1 = H
	}
	if x0 >= x1 || y0 >= y1 {
		return
	}
	for yy := y0; yy < y1; yy++ {
		base := (yy*W + x0) * 4
		for xx := x0; xx < x1; xx++ {
			cv.buf[base] = col.R
			cv.buf[base+1] = col.G
			cv.buf[base+2] = col.B
			cv.buf[base+3] = 255
			base += 4
		}
	}
}

// drawPoly — polyline walk with square stamps (coordinates logical).
func (cv *abCanvas) drawPoly(pts []abPt, col abRGBA, thick float64) {
	if len(pts) < 2 {
		return
	}
	ss := float64(plotSS)
	for i := 0; i+1 < len(pts); i++ {
		x0, y0 := pts[i].X*ss, pts[i].Y*ss
		x1, y1 := pts[i+1].X*ss, pts[i+1].Y*ss
		n := int(math.Max(math.Abs(x1-x0), math.Abs(y1-y0)))*2 + 1
		for k := 0; k <= n; k++ {
			t := float64(k) / float64(n)
			cv.fillRect((x0+(x1-x0)*t)/ss-thick/2, (y0+(y1-y0)*t)/ss-thick/2,
				thick, thick, col)
		}
	}
}

// ── stroke font (5×7 grid, polyline glyphs) ──────────────────────────────────

