// ══════════════════════════════════════════════════════════════════════════════
// AURORA REPORTS — REPORT.txt / final_report.md writers and the AbRun session
// collector. Files are plain-unicode (no ANSI): ❖/◆ ornaments, braille-free.
// ══════════════════════════════════════════════════════════════════════════════

type abSection struct {
	name string
	text string
}

type abRun struct {
	kind     string
	stamp    string
	dir      string
	sections []abSection
	metrics  map[string]string
}

func newAbRun(kind string) *abRun {
	stamp := time.Now().Format("20060102_150405")
	dir := filepath.Join("results", "run_"+stamp+"_"+kind)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		fmt.Fprintf(os.Stderr, "ERROR: cannot create report dir: %v\n", err)
		os.Exit(2)
	}
	return &abRun{kind: kind, stamp: stamp, dir: dir, metrics: map[string]string{}}
}

func (r *abRun) addSection(name, text string) {
	r.sections = append(r.sections, abSection{name, text})
}

// captureStdout — run fn() capturing stdout (console echo muted).
func captureStdout(fn func()) string {
	old := os.Stdout
	rp, wp, err := os.Pipe()
	if err != nil {
		fn()
		return ""
	}
	os.Stdout = wp
	done := make(chan string, 1)
	go func() {
		var buf bytes.Buffer
		_, _ = io.Copy(&buf, rp)
		done <- buf.String()
	}()
	fn()
	_ = wp.Close()
	os.Stdout = old
	return <-done
}

func (r *abRun) writeReportTxt() string {
	rule := strings.Repeat("═", 78)
	thin := strings.Repeat("─", 78)
	out := []string{}
	out = append(out, rule)
	out = append(out, "  "+abBrand)
	out = append(out, "  REPORT  ·  kind: "+r.kind+"  ·  "+time.Now().Format("2006-01-02T15:04:05"))
	out = append(out, rule)
	for _, s := range r.sections {
		out = append(out, "")
		out = append(out, "❖ "+s.name)
		out = append(out, thin)
		out = append(out, strings.TrimRight(s.text, " \t\n"))
	}
	out = append(out, "")
	out = append(out, rule)
	out = append(out, "❖ METRICS")
	out = append(out, thin)
	keys := make([]string, 0, len(r.metrics))
	for k := range r.metrics {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		out = append(out, fmt.Sprintf("  %-38s %s", k, r.metrics[k]))
	}
	out = append(out, rule)
	out = append(out, "◆ end of report — generated by the unified standalone port")
	p := filepath.Join(r.dir, "REPORT.txt")
	_ = os.WriteFile(p, []byte(strings.Join(out, "\n")+"\n"), 0o644)
	return p
}

func (r *abRun) writeReportMd() string {
	out := []string{}
	out = append(out, "# "+abBrand)
	out = append(out, "")
	out = append(out, "**Kind:** `"+r.kind+"`  |  **Stamp:** `"+r.stamp+"`  |  **Generated:** "+
		time.Now().Format("2006-01-02T15:04:05"))
	out = append(out, "")
	out = append(out, "> Единый автономный порт ядра meridian-spectral-observatory.")
	out = append(out, "> Эталон стиля и вычислений: `hp_audit_standal_one.jl` (HP·MERIDIAN AURORA).")
	out = append(out, "")
	out = append(out, "## Verdict")
	out = append(out, "")
	for _, k := range []string{"selftest", "suite", "battery"} {
		if v, has := r.metrics[k]; has {
			out = append(out, "- **"+k+":** "+v)
		}
	}
	out = append(out, "")
	out = append(out, "## Metrics")
	out = append(out, "")
	out = append(out, "| metric | value |")
	out = append(out, "|---|---|")
	keys := make([]string, 0, len(r.metrics))
	for k := range r.metrics {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		out = append(out, "| `"+k+"` | "+r.metrics[k]+" |")
	}
	out = append(out, "")
	out = append(out, "## Sections")
	out = append(out, "")
	for _, s := range r.sections {
		out = append(out, "### "+s.name)
		out = append(out, "")
		out = append(out, "```text")
		out = append(out, strings.TrimRight(s.text, " \t\n"))
		out = append(out, "```")
		out = append(out, "")
	}
	p := filepath.Join(r.dir, "final_report.md")
	_ = os.WriteFile(p, []byte(strings.Join(out, "\n")+"\n"), 0o644)
	return p
}

// ═══ AURORA HTML LAYER ═══

// ══════════════════════════════════════════════════════════════════════════════
// AURORA HTML — the self-contained report page: dark nebula theme, animated
// verdict ring (conic-gradient sweep), section cards, metric chips. Zero
// network: system font stack, inline CSS only. Print-friendly; honors
// prefers-reduced-motion.
// ══════════════════════════════════════════════════════════════════════════════

func htmlEsc(s string) string {
	r := strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;", `"`, "&#34;", "'", "&#39;")
	return r.Replace(s)
}

func abHtmlReport(run *abRun) string {
	verdict, verdictColor, score := "RUN", "#61dafb", 0.0
	if v, has := run.metrics["selftest"]; has {
		// e.g. "RESULT: 199/199 checks passed"
		if i := strings.Index(v, "RESULT:"); i >= 0 {
			f := strings.Fields(v[i:])
			if len(f) >= 2 && strings.Contains(f[1], "/") {
				parts := strings.SplitN(f[1], "/", 2)
				a, e1 := strconv.Atoi(parts[0])
				b, e2 := strconv.Atoi(strings.TrimSpace(parts[1]))
				if e1 == nil && e2 == nil && b > 0 {
					score = float64(a) / float64(b)
					verdict = fmt.Sprintf("%d/%d", a, b)
					if a == b {
						verdictColor = "#7ee787"
					} else {
						verdictColor = "#ff6b6b"
					}
				}
			}
		}
	}
	keys := make([]string, 0, len(run.metrics))
	for k := range run.metrics {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var chips strings.Builder
	for _, k := range keys {
		chips.WriteString("<div class=\"chip\"><span class=\"k\">" + htmlEsc(k) +
			"</span><span class=\"v\">" + htmlEsc(run.metrics[k]) + "</span></div>")
	}
	var secs strings.Builder
	for _, s := range run.sections {
		secs.WriteString("<details open><summary>❖ " + htmlEsc(s.name) +
			"</summary><pre>" + htmlEsc(s.text) + "</pre></details>")
	}
	doc := abHtmlTemplate()
	rep := strings.NewReplacer(
		"__SCORE__R", fmt.Sprintf("%.1f", score*100),
		"__VCOLOR__", verdictColor,
		"__VERDICT__", htmlEsc(verdict),
		"__CHIPS__", chips.String(),
		"__SECTIONS__", secs.String(),
		"__BRAND__", htmlEsc(abBrand),
		"__STAMP__", htmlEsc(run.stamp))
	p := filepath.Join(run.dir, "aurora_report.html")
	_ = os.WriteFile(p, []byte(rep.Replace(doc)), 0o644)
	return p
}

