// ══════════════════════════════════════════════════════════════════════════════
// buildReportPackage — selftest + zeros battery + metrics → the 3 files.
// ══════════════════════════════════════════════════════════════════════════════

func buildReportPackage() *abRun {
	run := newAbRun("report")
	zeta := loadZerosAuto(cliData)
	run.metrics["n_zeros"] = strconv.Itoa(len(zeta))
	if len(zeta) > 0 {
		run.metrics["gamma1"] = shortest(zeta[0])
		run.metrics["gammaN"] = shortest(zeta[len(zeta)-1])
	}

	// 1. golden selftest (199 anchors)
	installSelftestBar()
	st := captureStdout(func() { runSelftest(zeta, cliGolden) })
	auroraSilenceBar()
	run.addSection("GOLDEN SELFTEST (199 anchors)", st)
	res := ""
	for _, l := range strings.Split(st, "\n") {
		if strings.Contains(l, "RESULT:") {
			res = strings.TrimSpace(l)
		}
	}
	if res == "" {
		res = "see section"
	}
	run.metrics["selftest"] = res

	// 2. zeros battery (captured)
	zb := captureStdout(func() { runZeros(zeta) })
	run.addSection("ZERO-ANALYSIS BATTERY", zb)

	// 3. headline metrics
	sp := normalizedSpacings(zeta)
	mean := 0.0
	for _, s := range sp {
		mean += s
	}
	mean /= math.Max(1, float64(len(sp)))
	rmt := &RmtTable{}
	D, p := ksTest(rmt, sp)
	rMean, _ := meanAdjacentSpacingRatio(zeta)
	run.metrics["mean_spacing"] = fmt.Sprintf("%.6f", mean)
	run.metrics["ks_D"] = fmt.Sprintf("%.6f", D)
	run.metrics["ks_p"] = fmt.Sprintf("%.4g", p)
	run.metrics["r_mean"] = fmt.Sprintf("%.6f", rMean)
	run.metrics["selftest_pass"] = strconv.FormatBool(strings.Contains(res, "199/199"))

	pTxt := run.writeReportTxt()
	pMd := run.writeReportMd()
	pHtml := abHtmlReport(run)

	fmt.Println()
	fmt.Println("  " + c("◆ REPORT PACKAGE COMPLETE", "vio"))
	fmt.Println(kv("dir", run.dir))
	fmt.Println(kv("REPORT.txt", pTxt))
	fmt.Println(kv("final_report.md", pMd))
	fmt.Println(kv("aurora_report.html", pHtml))
	fmt.Println(kv("selftest", res))
	fmt.Println("  " + rule())
	return run
}

// ═══ EMBEDDED DATA + CLI + ENTRY ═══

// ══════════════════════════════════════════════════════════════════════════════
// EMBEDDED DATA — the zb64 payloads (zlib+base64, 76-col lines) are decoded
// lazily, once. CLI --data/--golden flags still win: if a flag is non-empty
// the file is read from disk; otherwise the embedded blobs are used and no
// disk file is required.
// ══════════════════════════════════════════════════════════════════════════════

func decodeZB64(s string) ([]byte, error) {
	var sb strings.Builder
	for _, r := range s {
		if r == '\n' || r == '\r' || r == ' ' || r == '\t' {
			continue
		}
		sb.WriteRune(r)
	}
	data, err := base64.StdEncoding.DecodeString(sb.String())
	if err != nil {
		return nil, err
	}
	zr, err := zlib.NewReader(bytes.NewReader(data))
	if err != nil {
		return nil, err
	}
	defer zr.Close()
	return io.ReadAll(zr)
}

var (
	embZerosOnce   bool
	embZerosCache  []float64
	embZerosErr    error
	embGoldenOnce  bool
	embGoldenCache []byte
	embGoldenErr   error
)

func loadZerosEmbedded() ([]float64, error) {
	if !embZerosOnce {
		embZerosOnce = true
		raw, err := decodeZB64(embZeros50kB64)
		if err != nil {
			embZerosErr = err
		} else {
			embZerosCache = parseZerosText(string(raw))
		}
	}
	return embZerosCache, embZerosErr
}

func goldenEmbedded() ([]byte, error) {
	if !embGoldenOnce {
		embGoldenOnce = true
		embGoldenCache, embGoldenErr = decodeZB64(embGoldenB64)
	}
	return embGoldenCache, embGoldenErr
}

// goldenSource — bytes for runSelftest: disk path if given, else embedded.
func goldenSource(path string) []byte {
	if path != "" {
		data, err := os.ReadFile(path)
		if err != nil {
			fmt.Fprintf(os.Stderr, "ERROR: golden file not found: %s\n", path)
			os.Exit(2)
		}
		return data
	}
	data, err := goldenEmbedded()
	if err != nil {
		fmt.Fprintf(os.Stderr, "ERROR: embedded golden payload: %v\n", err)
		os.Exit(2)
	}
	return data
}

func parseZerosText(text string) []float64 {
	fields := strings.Fields(text)
	z := make([]float64, 0, len(fields))
	for _, f := range fields {
		if v, err := strconv.ParseFloat(f, 64); err == nil {
			z = append(z, v)
		}
	}
	sort.Float64s(z)
	return z
}

// loadZerosAuto — disk path if given, else embedded zeros50k.
func loadZerosAuto(path string) []float64 {
	if path != "" {
		return loadZeros(path)
	}
	z, err := loadZerosEmbedded()
	if err != nil || len(z) == 0 {
		fmt.Fprintf(os.Stderr, "ERROR: embedded zeros50k payload unavailable: %v\n", err)
		os.Exit(2)
	}
	return z
}

// embeddedHealth — quick payload sanity for the doctor.
func embeddedHealth() (nZeros, nGoldenSections int, err error) {
	z, e1 := loadZerosEmbedded()
	if e1 != nil {
		return 0, 0, e1
	}
	nZeros = len(z)
	g, e2 := goldenEmbedded()
	if e2 != nil {
		return nZeros, 0, e2
	}
	var probe map[string]json.RawMessage
	if e3 := json.Unmarshal(g, &probe); e3 != nil {
		return nZeros, 0, e3
	}
	nGoldenSections = len(probe)
	return nZeros, nGoldenSections, nil
}

// ══════════════════════════════════════════════════════════════════════════════
// COMMAND BODIES (kernel behaviors kept 1:1)
// ══════════════════════════════════════════════════════════════════════════════

// runZeros — the `zeros` battery (verbatim body of the original dispatcher).
func runZeros(z []float64) {
	sp := normalizedSpacings(z)
	rmt := &RmtTable{}
	mean := 0.0
	for _, s := range sp {
		mean += s
	}
	mean /= float64(len(sp))
	variance := 0.0
	for _, s := range sp {
		variance += (s - mean) * (s - mean)
	}
	variance /= float64(len(sp) - 1)
	D, p := ksTest(rmt, sp)
	fmt.Printf("zeros: n=%d  g1=%.6f  gN=%.6f\n", len(z), z[0], z[len(z)-1])
	fmt.Printf("spacings: n=%d  mean=%.6f  var=%.6f\n", len(sp), mean, variance)
	fmt.Printf("KS  : D=%.6f  p=%.6e\n", D, p)
	fmt.Printf("CvM : W2=%.6f\n", cvmTest(rmt, sp))
	fmt.Printf("A2  : %.6f\n", andersonDarlingStat(rmt, sp))
	chi2v, dfv, pchi := chi2GueTest(rmt, sp, 30)
	fmt.Printf("chi2: %.4f  df=%d  p=%.6e\n", chi2v, dfv, pchi)
	r, nR := meanAdjacentSpacingRatio(z)
	fmt.Printf("<r> : %.6f  (n_r=%d)\n", r, nR)
	pos := unfoldedPositions(z)
	rng := NewMT19937(777)
	for _, L := range []float64{5.0, 10.0, 20.0, 50.0, 100.0} {
		fmt.Printf("S2(L=%6.1f) = %.6f\n", L, numberVariance(pos, L, 3000, rng))
	}
	for _, L := range []float64{5.0, 10.0, 20.0, 50.0} {
		fmt.Printf("D3(L=%6.1f) = %.6f\n", L, delta3Rigidity(pos, L, 300, 300, rng))
	}
}

// runHam — the `ham` tier (verbatim body of the original dispatcher).
func runHam() {
	type scn struct {
		name string
		cfg  AbCloudConfig
		l    int
	}
	scns := []scn{
		{"L8_open_a025_2vort", NewConfig(8, 8,
			[]Vortex{{X: 3.5, Y: 3.5, Q: 1.0}, {X: 6.5, Y: 6.5, Q: -1.0}},
			0.25, 1.0, "open", 0.0).With(96, "monumental"), 8},
		{"L10_open_a03_clean", NewConfig(10, 10, nil,
			0.3, 1.0, "open", 0.0).With(96, "monumental"), 10},
		{"L12_open_a03_clean", NewConfig(12, 12, nil,
			0.3, 1.0, "open", 0.0).With(96, "monumental"), 12},
	}
	for _, sc := range scns {
		t := hamTierCompute(sc.cfg, sc.l)
		fmt.Printf("%s  (L=%d, N=%d)\n", sc.name, sc.l, sc.cfg.Nx*sc.cfg.Ny)
		for c := 0; c < 3; c++ {
			fmt.Printf("  c%d: S(f=0.25)=%.9f  S(f=0.5)=%.9f  S(f=0.75)=%.9f  IPR=%.9f\n",
				c, t.s[c*3], t.s[c*3+1], t.s[c*3+2], t.ipr[c])
		}
		fmt.Printf("  TEE: slope=%.9f  gamma_top=%.9f  S_mean(f=0.5)=%.9f  S_std(f=0.5)=%.9f\n",
			t.slope, t.gammaTop, t.sMean[monTeeIdx[1]], t.sStd[monTeeIdx[1]])
		cb := centralBandEigs(t.ev, 0.6)
		rmt2 := &RmtTable{}
		dks, pks := rhBandKs(rmt2, cb)
		r, ncb := meanAdjacentSpacingRatio(cb)
		fmt.Printf("  RH metrics (central 0.6): n=%d  D=%.6f  p=%.4e  <r>=%.6f\n", ncb, dks, pks, r)
	}
}

// runHP — the H1 primary detector (verbatim body of the original dispatcher).
func runHP(z []float64) {
	n := len(z)
	om := make([]float64, 726)
	for k := range om {
		om[k] = 0.3 + 0.004*float64(k)
	}
	w := make([]float64, n)
	for i := 0; i < n; i++ {
		w[i] = 0.5 * (1.0 - math.Cos(2*PI*float64(i)/float64(n-1)))
	}
	sw2 := 0.0
	for _, wi := range w {
		sw2 += wi * wi
	}
	P := make([]float64, len(om))
	for fi, omv := range om {
		re, im := 0.0, 0.0
		for i := 0; i < n; i++ {
			re += w[i] * math.Cos(omv*z[i])
			im -= w[i] * math.Sin(omv*z[i])
		}
		P[fi] = (re*re + im*im) / sw2
	}
	Ps := append([]float64(nil), P...)
	sort.Float64s(Ps)
	med := 0.5 * (Ps[len(Ps)/2-1] + Ps[len(Ps)/2])
	fmt.Printf("H1 primary detector on %d positions:\n", n)
	hits := 0
	for _, pr := range []int{2, 3, 5, 7, 11, 13} {
		tgt := math.Log(float64(pr))
		best, bd := 0, math.Inf(1)
		for i, o := range om {
			d := math.Abs(o - tgt)
			if d < bd {
				bd, best = d, i
			}
		}
		snr := P[best] / med
		if snr >= 10.0 {
			hits++
		}
		mark := "-"
		if snr >= 10.0 {
			mark = "PEAK"
		}
		fmt.Printf("  SNR(log %2d) = %.6e  [%s]\n", pr, snr, mark)
	}
	fmt.Printf("  verdict: %d/6 prime harmonics above SNR 10\n", hits)
}

// ══════════════════════════════════════════════════════════════════════════════
// AURORA WRAPPERS + DISPATCHER
// ══════════════════════════════════════════════════════════════════════════════

var (
	cliData   string
	cliGolden string
	cliNS     []int64
	cliOffset int64
	cliMC     = 200
	cliSeed   = 777
	cliPlain  bool
)

func selftestRun(plain bool) bool {
	z := loadZerosAuto(cliData)
	if !plain {
		sectionHead("GOLDEN SELFTEST (199 anchors)")
		installSelftestBar()
	} else {
		auroraSilenceBar()
	}
	ok := runSelftest(z, cliGolden)
	if !plain {
		auroraSilenceBar()
		if ok {
			fmt.Println("  verdict: " + badge("199/199 · BIT-EXACT PARITY", "ok"))
		} else {
			fmt.Println("  verdict: " + badge("SELFTEST FAILED", "bad"))
		}
	}
	return ok
}

func zerosRun() {
	z := loadZerosAuto(cliData)
	if len(cliNS) > 0 && cliNS[0] > 0 && cliNS[0] < int64(len(z)) {
		z = z[:cliNS[0]]
	}
	sectionHead(fmt.Sprintf("ZERO-ANALYSIS BATTERY (n = %d)", len(z)))
	runZeros(z)
	fmt.Println("  " + rule())
}

func sweepRun(head bool) {
	z := loadZerosAuto(cliData)
	ns := cliNS
	if len(ns) == 0 {
		ns = []int64{100, 500, 1000, 5000, 10000, 50000}
	}
	if head {
		sectionHead("bN LADDER SWEEP")
	}
	fmt.Println("  N        b(N)")
	for _, n := range ns {
		fmt.Printf("%6d  %.8f\n", n, computeBN(z, n, 0))
	}
	if head {
		fmt.Println("  " + rule())
	}
}

func plotsRun() {
	pdir := filepath.Join("results", "plots_"+time.Now().Format("20060102_150405"))
	if err := os.MkdirAll(pdir, 0o755); err != nil {
		fmt.Fprintf(os.Stderr, "ERROR: cannot create plots dir: %v\n", err)
		os.Exit(2)
	}
	z := loadZerosAuto(cliData)
	sectionHead("PLOTS — 600 dpi PNG battery (3600×2250, ss=2)")
	pths := abPlotsRun(pdir, z)
	for _, p := range pths {
		fmt.Println(kv("wrote", p))
	}
	fmt.Println("  " + rule())
}

func reportRun() {
	sectionHead("REPORT PACKAGE (txt + md + html)")
	buildReportPackage()
}

const abUsage = `usage: abcloud_unified.go <command> [options]

commands:
  menu                          interactive AURORA menu (default, no args)
  selftest [--plain]            golden parity check (199 anchors, embedded)
  zeros [--n N] [--data P]      zero-analysis battery (spacings/KS/CvM/AD)
  suite                         portable test suite (kernel subset)
  ham                           Monumental TEE/entropy tier (L8/L10/L12)
  bN --N n [--offset k]         b(N) statistic
  gram --n n...                 Gram points
  test11 [--mc M] [--seed S]    Anderson-Darling honest MC
  hp                            H1 primary detector (prime harmonics)
  sweep                         b(N) ladder sweep
  report                        full report package (txt + md + html)
  plots                         600-dpi PNG battery (3 charts)
  doctor                        environment probe
  banner                        AURORA wordmark
  version                       print version
  help                          this text

options:
  --data P                      zeros file path   (default: embedded blob)
  --golden P                    golden JSON path  (default: embedded blob)
  --plain                       no AURORA decorations (selftest)
`

func main() {
	auroraProbe()
	args := os.Args[1:]
	if len(args) == 0 {
		menuLoop()
		return
	}
	cmd := args[0]
	for i := 1; i < len(args); i++ {
		a := args[i]
		switch a {
		case "--data":
			if i+1 < len(args) {
				i++
				cliData = args[i]
			}
		case "--golden":
			if i+1 < len(args) {
				i++
				cliGolden = args[i]
			}
		case "--N", "--n":
			for i+1 < len(args) && !strings.HasPrefix(args[i+1], "-") {
				i++
				if v, err := strconv.ParseInt(args[i], 10, 64); err == nil {
					cliNS = append(cliNS, v)
				}
			}
		case "--offset":
			if i+1 < len(args) {
				i++
				cliOffset, _ = strconv.ParseInt(args[i], 10, 64)
			}
		case "--mc":
			if i+1 < len(args) {
				i++
				cliMC, _ = strconv.Atoi(args[i])
			}
		case "--seed":
			if i+1 < len(args) {
				i++
				cliSeed, _ = strconv.Atoi(args[i])
			}
		case "--plain":
			cliPlain = true
		}
	}

	switch cmd {
	case "menu":
		menuLoop()
	case "selftest":
		if !selftestRun(cliPlain) {
			os.Exit(1)
		}
	case "zeros":
		zerosRun()
	case "suite":
		z := loadZerosAuto(cliData)
		runSuite(z)
	case "ham":
		runHam()
	case "bN":
		z := loadZerosAuto(cliData)
		ns := cliNS
		if len(ns) == 0 {
			ns = []int64{100, 1000, 10000}
		}
		for _, n := range ns {
			fmt.Printf("b(N=%6d, offset=%d) = %.10f\n", n, cliOffset, computeBN(z, n, cliOffset))
		}
	case "gram":
		ns := cliNS
		if len(ns) == 0 {
			ns = []int64{1, 10, 100}
		}
		for _, n := range ns {
			fmt.Printf("g_%d = %.10f\n", n, gramPoint(n))
		}
	case "test11":
		z := loadZerosAuto(cliData)
		sp := normalizedSpacings(z)
		rmt := &RmtTable{}
		A2 := andersonDarlingStat(rmt, sp)
		fmt.Printf("Test 11 (honest): exact A2 on n=%d spacings: %.6f\n", len(sp), A2)
		if cliMC > 0 {
			rng := NewMT19937(uint32(cliSeed))
			buf := make([]float64, len(sp))
			count := 0
			for it := 0; it < cliMC; it++ {
				rmt.Sample(rng, buf)
				if andersonDarlingStat(rmt, buf) >= A2 {
					count++
				}
			}
			fmt.Printf("MC null (%d draws): p = %.6f  (%d/%d >= A2)\n", cliMC,
				float64(count+1)/float64(cliMC+1), count, cliMC)
		}
	case "hp":
		runHP(loadZerosAuto(cliData))
	case "sweep":
		sweepRun(true)
	case "report":
		reportRun()
	case "plots":
		plotsRun()
	case "doctor":
		if !doctor() {
			os.Exit(1)
		}
	case "banner":
		banner()
	case "version":
		fmt.Println(abBrand + " " + abVersion)
	case "help", "-h", "--help":
		fmt.Print(abUsage)
	default:
		fmt.Fprintf(os.Stderr, "unknown command: %s\n\n%s\n", cmd, abUsage)
		os.Exit(2)
	}
}
